def NBitBinary(N):
    def backtrack(current, ones, zeros):
        if len(current) == N:
            result.append(current)
            return
        if ones < N:
            backtrack(current + '1', ones + 1, zeros)
        if zeros < ones:
            backtrack(current + '0', ones, zeros + 1)

    result = []
    backtrack('', 0, 0)
    return result

